const fs = require('fs');
const ExcelJS = require('exceljs');

async function updateEmployeesFromBizno() {
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  const backupSrc = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명_backup_11847_12346.xlsx';

  if (!fs.existsSync(filePath)) {
    console.log('Restoring from backup...');
    fs.copyFileSync(backupSrc, filePath);
  }

  console.log('Reading Bizno 500 rows TSV...');
  const tsvLines = fs.readFileSync('bizno_filtered_result.tsv', 'utf-8').split('\n').filter(l => l.trim().length > 0);
  console.log('Total Bizno rows:', tsvLines.length);

  console.log('Loading workbook...');
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  const orangeFill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFFFA500' } // Standard Orange
  };

  let updatedCount = 0;

  for (let i = 0; i < tsvLines.length; i++) {
    const rowNum = 11847 + i;
    const row = sheet.getRow(rowNum);
    const p = tsvLines[i].split('\t');

    // p[11] is employee count from Bizno
    const rawEmp = p[11] ? p[11].trim() : '';
    const empNum = rawEmp !== '' && !isNaN(rawEmp) ? Number(rawEmp) : (rawEmp !== '' ? rawEmp : null);

    const cell = row.getCell(15);
    cell.value = empNum;

    if (empNum !== null) {
      cell.fill = orangeFill;
      updatedCount++;
    }

    row.commit();
  }

  console.log('Updated employee count for ' + updatedCount + ' rows.');
  console.log('Writing file to temporary path...');
  const tempPath = filePath + '.tmp';
  await workbook.xlsx.writeFile(tempPath);

  console.log('Overwriting target file...');
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
  fs.renameSync(tempPath, filePath);

  console.log('Successfully saved employee counts from Bizno! Final size:', fs.statSync(filePath).size);
}

updateEmployeesFromBizno().catch(console.error);
